begin;
set local search_path=public,extensions;
select plan(44);

select ok((select count(*)=7 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['diagnostic_solution_sets','diagnostic_solution_options','diagnostic_solution_decisions','solution_bundle_versions','solution_bundle_items','benchmark_privacy_policies','benchmark_publications'])),'seven public solution, bundle and benchmark tables exist');
select ok((select count(*)=2 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private'and c.relkind='r'and c.relname=any(array['benchmark_contributions','benchmark_computations'])),'raw benchmark data stays in private schema');
select ok((select count(*)=9 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where(n.nspname='public'and c.relname=any(array['diagnostic_solution_sets','diagnostic_solution_options','diagnostic_solution_decisions','solution_bundle_versions','solution_bundle_items','benchmark_privacy_policies','benchmark_publications']))or(n.nspname='private'and c.relname=any(array['benchmark_contributions','benchmark_computations']))),'RLS is enabled on all nine tables');
select ok((select count(*)=7 from pg_policies where schemaname='public'and tablename=any(array['diagnostic_solution_sets','diagnostic_solution_options','diagnostic_solution_decisions','solution_bundle_versions','solution_bundle_items','benchmark_privacy_policies','benchmark_publications'])),'all public tables have explicit read policies');
select ok(not has_table_privilege('authenticated','private.benchmark_contributions','SELECT')and not has_table_privilege('service_role','private.benchmark_contributions','SELECT'),'raw benchmark rows have no direct API grants');
select ok(not has_table_privilege('authenticated','public.diagnostic_solution_sets','INSERT')and not has_table_privilege('authenticated','public.solution_bundle_versions','INSERT')and not has_table_privilege('authenticated','public.benchmark_publications','INSERT'),'authenticated cannot bypass command APIs');
select ok(not has_table_privilege('anon','public.benchmark_publications','SELECT')and not has_table_privilege('anon','public.solution_bundle_versions','SELECT'),'anonymous access is denied');
select ok((select count(*)=9 from pg_trigger where tgname=any(array['diagnostic_solution_sets_immutable','diagnostic_solution_options_immutable','diagnostic_solution_decisions_immutable','solution_bundle_versions_immutable','solution_bundle_items_immutable','benchmark_privacy_policies_immutable','benchmark_contributions_immutable','benchmark_computations_immutable','benchmark_publications_immutable'])and not tgisinternal),'all histories are immutable');
select ok(not exists(select 1 from information_schema.columns where table_schema in('public','private')and table_name=any(array['diagnostic_solution_options','solution_bundle_versions','solution_bundle_items','benchmark_privacy_policies','benchmark_contributions','benchmark_computations','benchmark_publications'])and data_type in('real','double precision')),'scores and values use no floating point');
select is((select data_type from information_schema.columns where table_schema='public'and table_name='diagnostic_solution_options'and column_name='estimated_amount_minor'),'bigint','solution estimates use minor units');
select is((select data_type from information_schema.columns where table_schema='public'and table_name='solution_bundle_versions'and column_name='total_amount_minor'),'bigint','bundle totals use minor units');
select is((select data_type from information_schema.columns where table_schema='private'and table_name='benchmark_contributions'and column_name='value_exact'),'numeric','benchmark inputs use exact numeric');
select ok(exists(select 1 from pg_constraint where conrelid='public.diagnostic_solution_options'::regclass and contype='c'and pg_get_expr(conbin,conrelid)like'%ESSENTIAL%'and pg_get_expr(conbin,conrelid)like'%STANDARD%'and pg_get_expr(conbin,conrelid)like'%ADVANCED%'),'solution levels are constrained to the three Gold Master tiers');
select ok(exists(select 1 from pg_constraint where conrelid='public.diagnostic_solution_options'::regclass and contype='u'and pg_get_constraintdef(oid)like'%solution_set_id, level%'),'each solution set has at most one row per level');
select ok((select p.prosrc like'%jsonb_array_length(p_options)<>3%'and p.prosrc like'%level_count<>3%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solution command requires exactly all three tiers');
select ok((select p.prosrc like'%current_published_version_id<>sv.id%'and p.prosrc like'%source_policy_snapshot%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solutions bind current published service versions and policy provenance');
select ok((select p.prosrc like'%expected_score_bps%'and p.prosrc like'%content_hash%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solution scores and content are reproducible');
select ok((select p.prosrc like'%begin_contract_command%'and p.prosrc like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solution creation is idempotent');
select ok((select p.prosrc like'%diagnostic.solution_set.created%'and p.prosrc like'%DiagnosticSolutionSetCreatedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solution creation is audited and outboxed');
select ok((select p.prosrc like'%CLIENT_OWNER%'and p.prosrc like'%CLIENT_ADMIN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_anomaly_solution_set'),'solution creation enforces tenant roles');
select ok((select p.prosrc like'%CLIENT_BUYER%'and p.prosrc like'%ACCEPTED%'and p.prosrc like'%REJECTED%'and p.prosrc like'%DEFERRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_solution_decision'),'human client decisions are explicit');
select ok((select indexdef like'%WHERE (decision = ''ACCEPTED''%'from pg_indexes where schemaname='public'and indexname='diagnostic_solution_one_accept_uidx'),'only one tier may be accepted per set');
select ok((select p.prosrc not like'%service_requests%'and p.prosrc not like'%missions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_solution_decision'),'solution decision never orders or creates a mission');
select ok((select p.prosrc like'%jsonb_array_length(p_items)<2%'and p.prosrc like'%library_count<2%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_solution_bundle'),'bundles require at least two source items across two libraries');
select ok((select p.prosrc like'%current_published_version_id<>sv.id%'and p.prosrc like'%source_manifest_hash%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_solution_bundle'),'bundles freeze published service versions and source manifest');
select ok((select p.prosrc like'%group by dedupe_key%'and p.prosrc like'%source_count%'and p.prosrc like'%provenance%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_solution_bundle'),'bundle fusion preserves provenance while deduplicating');
select ok((select p.prosrc like'%max(amount_minor)%'and p.prosrc like'%sum(amount_minor)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_solution_bundle'),'deduplicated bundle amount is deterministic and exact');
select ok(exists(select 1 from pg_constraint where conrelid='public.solution_bundle_versions'::regclass and contype='u'and pg_get_constraintdef(oid)like'%organization_id, bundle_key, version%'),'bundle versions are unique per tenant and key');
select ok((select p.prosrc like'%begin_contract_command%'and p.prosrc like'%solution.bundle.published%'and p.prosrc like'%SolutionBundlePublishedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_solution_bundle'),'bundle publication is idempotent, audited and outboxed');
select ok(exists(select 1 from pg_constraint where conrelid='public.benchmark_privacy_policies'::regclass and contype='c'and pg_get_expr(conbin,conrelid)like'%minimum_group_size >= 5%'),'privacy policy cannot lower group size below five');
select ok(exists(select 1 from pg_constraint where conrelid='public.benchmark_privacy_policies'::regclass and contype='c'and pg_get_expr(conbin,conrelid)like'%minimum_period_days >= 7%'),'privacy policy enforces a minimum observation period');
select ok((select indexdef like'%WHERE (status = ''ACTIVE''%'from pg_indexes where schemaname='public'and indexname='benchmark_one_active_policy_uidx'),'only one privacy policy is active');
select ok((select p.prosrc like'%aal2%'and p.prosrc like'%SUPER_ADMIN%'and p.prosrc like'%MATRICIA_ADMIN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_benchmark_privacy_policy'),'privacy policy publication requires central MFA');
select ok((select p.prosrc like'%max(version)%'and p.prosrc like'%status=''RETIRED''%'and p.prosrc like'%effective_to%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_benchmark_privacy_policy'),'privacy policy changes are versioned, dated and never overwritten');
select ok((select p.prosrc like'%private.benchmark_contributions%'and p.prosrc like'%source_hash%'and p.prosrc like'%input_version%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'benchmark submissions preserve reproducible private provenance');
select ok((select p.prosrc like'%has_org_role%'and p.prosrc like'%begin_contract_command%'and p.prosrc like'%audit_events%'and p.prosrc like'%BenchmarkContributionAcceptedV3%'and p.prosrc like'%benchmark_registry_versions%'and p.prosrc like'%benchmark_verified_sources%'and p.prosrc like'%source_row.registry_version_id=registry.id%'and p.prosrc like'%source_row.binding_hash=private.canonical_request_hash%'and p.prosrc like'%source_verification_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'final benchmark submission is tenant-scoped, exactly registry/provenance bound, idempotent, audited and outboxed');
select ok((select p.prosrc like'%auth.role()<>''service_role''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'only the trusted worker can compute benchmarks');
select ok((select p.prosrc like'%distinct on(organization_id)%'and p.prosrc like'%n<pol.minimum_group_size%'and p.prosrc like'%BENCHMARK_SUPPRESSED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'latest contribution per tenant is used and small cohorts are suppressed');
select ok((select p.prosrc like'%round(exact_mean/pol.rounding_increment)*pol.rounding_increment%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'published means use versioned rounding');
select ok((select p.prosrc like'%group_size_band%'and p.prosrc like'%FIVE_MEMBER_BAND%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'exact cohort size is hidden in a band');
select ok((select p.prosrc like'%release_delay_days%'and p.prosrc like'%minimum_period_days%'and p.prosrc like'%BenchmarkPublishedV1%'and p.prosrc like'%benchmark.published%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='compute_anonymized_benchmark'),'computation enforces versioned windows and writes audit plus Outbox');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name='benchmark_publications'and column_name in('organization_id','contributor_count','exact_mean','source_hash')),'public benchmark rows expose no tenant, exact group size or raw value');
select ok((select count(*)=6 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_anomaly_solution_set','record_solution_decision','publish_solution_bundle','publish_benchmark_privacy_policy','submit_benchmark_contribution','compute_anonymized_benchmark'])),'all six commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['create_anomaly_solution_set','record_solution_decision','publish_solution_bundle','publish_benchmark_privacy_policy','submit_benchmark_contribution'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'user commands are unavailable to anon and service role');

select * from finish();rollback;
